const { Client } = require('pg');
const c = new Client({ host: '/var/tmp/d4142', port: 21441, user: process.argv[2], database: 'seg41' });

// MAL: el texto de la persona se pega dentro del SQL.
async function buscarMal(nombre) {
  const sql = `select id, destinatario, estado from envios where destinatario = '${nombre}'`;
  const r = await c.query(sql);               // sin parámetros: el protocolo simple admite varias sentencias
  return (Array.isArray(r) ? r[0] : r).rows;
}
// BIEN: el SQL y el dato viajan por separado.
async function buscarBien(nombre) {
  return (await c.query('select id, destinatario, estado from envios where destinatario = $1', [nombre])).rows;
}

